from collections import Counter, deque

def solve(g):
    h,w=len(g),len(g[0])
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    seen=[[False]*w for _ in range(h)]; out=[r[:] for r in g]
    for i in range(h):
        for j in range(w):
            if not seen[i][j] and g[i][j]!=bg:
                c=g[i][j]; q=deque([(i,j)]); seen[i][j]=True; cells=[]
                while q:
                    a,b=q.popleft(); cells.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<h and 0<=nb<w and not seen[na][nb] and g[na][nb]==c:
                            seen[na][nb]=True; q.append((na,nb))
                if len(cells)>=2:
                    rs=[a for a,b in cells]; cs=[b for a,b in cells]
                    for a in range(min(rs),max(rs)+1):
                        for b in range(min(cs),max(cs)+1):
                            out[a][b]=c
                else:
                    out[i][j]=bg
    return out

