                c=g[i2][j2]; q=deque([(i2,j2)]); seen[i2][j2]=True; cells=[]
                while q:
                    a,b=q.popleft(); cells.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<h and 0<=nb<w and not seen[na][nb] and g[na][nb]==c:
                            seen[na][nb]=True; q.append((na,nb))
                cnt=Counter(g[a][b] for a,b in cells)
                dom,_=cnt.most_common(1)[0]
                comps.append({'cells':set(cells),'dom':dom})
    blocks=[x for x in comps if len(x['cells'])>=2]
    others=[x for x in comps if len(x['cells'])==1]
    for blk in blocks:
        rs=[p[0] for p in blk['cells']]; cs=[p[1] for p in blk['cells']]
        for a in range(min(rs),max(rs)+1):
            for b in range(min(cs),max(cs)+1):
                out[a][b]=blk['dom']
