        (a,b)=next(iter(o_['cells']))
        cand=[blk for blk in blocks
              if min(p[0] for p in blk['cells'])<=a<=max(p[0] for p in blk['cells'])
              and min(p[1] for p in blk['cells'])<=b<=max(p[1] for p in blk['cells'])]
        if touch:
            cand.extend(blk for blk in blocks
                       if any(abs(aa-a)<=1 and abs(bb-b)<=1 for aa,bb in blk['cells']))
