def comps4(a):
    H,W=a.shape; seen=np.zeros_like(a,bool); out=[]
    for i in range(H):
        for j in range(W):
            if not seen[i,j]:
                col=int(a[i,j]); stack=[(i,j)]; comp=[]; seen[i,j]=True
                while stack:
                    x,y=stack.pop(); comp.append((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx,ny=x+dx,y+dy
