import numpy as np, os, re, json
from collections import Counter
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); GG={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in GG and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            GG[k]=[[int(x) for x in r] for r in rows]
    return GG
GG=load(); print(sorted(GG))
def comps(a):
    # per-color 4-connected comps
    H,W=a.shape; seen=np.zeros_like(a,bool); out=[]
    for i in range(H):
        for j in range(W):
            if not seen[i,j]:
                col=a[i,j]; stack=[(i,j)]; comp=[]; seen[i,j]=True
                while stack:
                    x,y=stack.pop(); comp.append((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx,ny=x+dx,y+dy
                        if 0<=nx<H and 0<=ny<W and not seen[nx,ny] and a[nx,ny]==col:
                            seen[nx,ny]=True; stack.append((nx,ny))
                out.append((col,comp))
    return out
def f(grid):
    a=np.array(grid); H,W=a.shape
    vals,ct=Counter(a.flatten()),Counter()
    for v in vals: ct[v]+=1
    bg=min(ct,key=ct.get)
    cs=comps(a); shapes=[]; strays=[]
    for col,comp in cs:
        (shapes if len(comp)>=2 else strays).append((col,comp))
    res=np.full_like(a,bg,dtype=int)
    for col,comp in shapes:
        rs=[p[0] for p in comp]; ccs=[p[1] for p in comp]
        r0,r1,c0,c1=min(rs),max(rs),min(ccs),max(ccs)
        dom=Counter(a[x,y] for x,y in comp).most_common(1)[0][0]
        res[r0:r1+1,c0:c1+1]=dom
    for col,(r,c) in strays:
        res[r,c]=bg
        for s in shapes:
            s2,_c=s
            rs=[p[0] for p in _c]; ccs=[p[1] for p in _c]
            r0,r1,c0,c1=min(rs),max(rs),min(ccs),max(ccs)
            if r0<=r<=r1 and c0<=c<=c1:
                res[r,c]=s2
    return res.tolist()
for k in ['Demo pair 2','Demo pair 3','Demo pair 4']:
    ok=f(GG[k+' input'])==GG[k+' output']
    print(k,'match:',ok)
    if not ok:
        o=np.array(f(GG[k+' input'])); e=np.array(GG[k+' output'])
