import numpy as np, os, re, json
from collections import Counter
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def comps(a):
    H,W=a.shape; seen=np.zeros_like(a,bool); out=[]
    for i in range(H):
        for j in range(W):
            if not seen[i,j]:
                col=int(a[i,j]); stack=[(i,j)]; comp=[]; seen[i,j]=True
                while stack:
                    x,y=stack.pop(); comp.append((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx,ny=x+dx,y+dy
                        if 0<=nx<H and 0<=ny<W and not seen[nx,ny] and int(a[nx,ny])==col:
                            seen[nx,ny]=True; stack.append((nx,ny))
                out.append((col,comp))
    return out
def f(grid):
    a=np.array(grid); H,W=a.shape
    ct=Counter(int(x) for x in a.flatten()); bg=min(ct,key=ct.get)
    cs=comps(a)
    res=a.copy()
    for col,comp in cs:
        if len(comp)==1:
            r,c=comp[0]
            nb=[]
            for dr in (-1,0,1):
                for dc in (-1,0,1):
                    if dr==dc==0: continue
                    nr,nc=r+dr,c+dc
                    if 0<=nr<H and 0<=nc<W: nb.append(int(a[nr,nc]))
            nonbg=[v for v in nb if v!=bg]
            if nonbg:
                mc,_=Counter(nonbg).most_common(1)[0]
                res[r,c]=mc
    return res.tolist()
for k in ['Demo pair 2','Demo pair 3','Demo pair 4']:
    o=np.array(f(G[k+' input'])); e=np.array(G[k+' output'])
    print(k,'match:',(o==e).all())
print(json.dumps(f(G['Test input'])))

